fication_status":"unreviewed","tags":["architectuur","stedenbouw","design"],"photos":[],"is_art_museum":true},{"id":"e07c6573-a3c2-58c6-b3a5-bdbfa2ac00af","inventory_key":"art-audit:254","name":"Ruurd Wiersma Museum","city":"Birdaard","province":"Friesland","street_address":"Mounewei 6-7","postal_code":"9111 HB","country":"NL","website_url":"https://ruurdwiersma.nl/","latitude":null,"longitude":null,"summary":"Ontdek de kleurrijke wereld van Ruurd Wiersma. Zijn schilderijen brengen het Friese leven en landschap op een eigen, directe manier in beeld. De persoonlijke omgeving maakt zijn verbeelding extra dichtbij.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["naïeve kunst","schilderkunst","kunstenaarsmuseum"],"photos":[],"is_art_museum":true},{"id":"3bdeae20-fec7-5b7a-921a-03ccbc47a814","inventory_key":"wikipedia:Noord-Brabant:andreasschotelmuseum:esbeek","name":"Andreas Schotel Museum","city":"Esbeek","province":"Noord-Brabant","street_address":"Dorpsstraat 2","postal_code":"5058 EG","country":"NL","website_url":"https://andreasschotel.nl/","latitude":null,"longitude":null,"summary":"Ontdek de scherpe blik van Andreas Schotel. Zijn grafiek en tekeningen leggen mensen, arbeid en landschap vast. Het museum in Esbeek laat zien hoe het dagelijkse leven een blijvende bron van beelden kan zijn.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["grafiek","tekenkunst","kunstenaarsmuseum"],"photos":[],"is_art_museum":true},{"id":"5280274f-f3ec-5f2e-989c-41e43941be69","inventory_key":"museum-nl:marie-tak-van-poortvliet-museum","name":"Marie Tak van Poortvliet Museum","city":"Domburg","province":"Zeeland","street_address":"Ooststraat 10a","postal_code":"4357 BE","country":"NL","website_url":"https://marietakmuseum.nl/home/langs-paden-van-verlangen.html","latitude":51.563367,"longitude":3.498357,"summary":"Ontdek de kunstenaars die zich door Domburg lieten inspireren. Wisselende tentoonstellingen belichten de artistieke geschiedenis van de badplaats en haar omgeving. Licht, kleur en landschap keren steeds in nieuwe gedaanten terug.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","kunstenaarskolonie","moderne kunst"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/1/13/Marie-Tak-van-Poortvlietmus.jpg","caption":"Marie Tak van Poortvliet Museum — Marie-Tak-van-Poortvlietmus","credit":"A3diet","source_url":"https://commons.wikimedia.org/wiki/File:Marie-Tak-van-Poortvlietmus.jpg","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"21d02dab-d642-558a-8ecd-1b6f1dcf721e","inventory_key":"museum-nl:de-appel","name":"De Appel","city":"Amsterdam","province":"Noord-Holland","street_address":"Tolstraat 160","postal_code":"1074 VM","country":"NL","website_url":"https://deappel.nl/en/","latitude":null,"longitude":null,"summary":"Ontdek nieuwe ontwikkelingen in hedendaagse kunst bij De Appel. Tentoonstellingen en performances geven ruimte aan kunstenaars en onverwachte ideeën. De instelling verbindt experiment met gesprekken over kunst en de wereld eromheen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","performance","experiment"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/160%2C_Cin%C3%A9toltheater%2C_overzicht_-_Amsterdam_-_20021151_-_RCE.jpg/1280px-160%2C_Cin%C3%A9toltheater%2C_overzicht_-_Amsterdam_-_20021151_-_RCE.jpg","caption":"De Appel — 160, Cinétoltheater, overzicht - Amsterdam - 20021151 - RCE","credit":"Gerard Dukker","source_url":"https://commons.wikimedia.org/wiki/File:160,_Cin%C3%A9toltheater,_overzicht_-_Amsterdam_-_20021151_-_RCE.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"681edb02-d5c5-587f-8e5d-9351bae76ea7","inventory_key":"art-audit:259","name":"Arcam Architectuurcentrum Amsterdam","city":"Amsterdam","province":"Noord-Holland","street_address":"Prins Hendrikkade 600","postal_code":"1011 VX","country":"NL","website_url":"https://www.arcam.nl/","latitude":null,"longitude":null,"summary":"Ontdek Amsterdam als ontworpen stad. Arcam presenteert tentoonstellingen en informatie over architectuur en stedelijke ontwikkeling. Gebouwen, plannen en routes helpen je om de omgeving buiten met een nieuwe blik te bekijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["architectuur","stedenbouw","design"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Amsterdam_082.jpg/1280px-Amsterdam_082.jpg","caption":"Arcam Architectuurcentrum Amsterdam — Amsterdam 082","credit":"Panhard","source_url":"https://commons.wikimedia.org/wiki/File:Amsterdam_082.jpg","license":"CC BY 2.5"}],"is_art_museum":true},{"id":"186120ae-4217-5e1e-99a4-cfe625fea09c","inventory_key":"museum-nl:landhuis-oud-amelisweerd","name":"Landhuis Oud Amelisweerd","city":"Bunnik","province":"Utrecht","street_address":"Koningslaan 9","postal_code":"3981 HD","country":"NL","website_url":"https://landhuisoudamelisweerd.nl/","latitude":52.067447,"longitude":5.169655,"summary":"Ontdek kunst in Landhuis Oud Amelisweerd. Tijdelijke presentaties ontmoeten historische interieurs en bijzonder Chinees behang. Het huis verbindt beeldende kunst met zijn groene omgeving en biedt telkens een nieuwe reden om terug te komen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Landhuis_Oud_Amelisweerd%2C_Bunnik%2C_Nederland_Apr_11%2C_2026_03-43-56_PM.jpeg/1280px-Landhuis_Oud_Amelisweerd%2C_Bunnik%2C_Nederland_Apr_11%2C_2026_03-43-56_PM.jpeg","caption":"Landhuis Oud Amelisweerd — Landhuis Oud Amelisweerd, Bunnik, Nederland Apr 11, 2026 03-43-56 PM","credit":"JakobHosp","source_url":"https://commons.wikimedia.org/wiki/File:Landhuis_Oud_Amelisweerd,_Bunnik,_Nederland_Apr_11,_2026_03-43-56_PM.jpeg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"124d28bc-7cca-56a2-807a-fb5afc5f8eb0","inventory_key":"museum-nl:heiligenbeeldenmuseum","name":"Heiligenbeeldenmuseum","city":"Vorden","province":"Gelderland","street_address":"Ruurloseweg 101","postal_code":"7251 LD","country":"NL","website_url":"https://www.heiligenbeeldenmuseum.nl/","latitude":52.101895,"longitude":6.358984,"summary":"Ontdek de expressie van heiligenbeelden in een kerk van Pierre Cuypers. De verzameling toont uiteenlopende manieren waarop figuren, attributen en gebaren betekenis krijgen. Thema-exposities geven steeds een ander accent aan deze beeldtraditie.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["religieuze kunst","beeldhouwkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Antoniuskerk_Vorden_zijaanzicht.jpg/1280px-Antoniuskerk_Vorden_zijaanzicht.jpg","caption":"Heiligenbeeldenmuseum — Antoniuskerk Vorden zijaanzicht","credit":"Ansfreedom","source_url":"https://commons.wikimedia.org/wiki/File:Antoniuskerk_Vorden_zijaanzicht.jpg","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
